        b_fp16 = self.bias.to(torch.float16)         # bias shape [out_features]
        # Custom op expects (x, w, bias) and performs y = ReLU(x @ w.T + bias)
        return custom_ops_lib.gemm_add_relu_custom(x_fp16, w_fp16, b_fp16)
